<?php
/** SmartToolz Video public channel pages and creator channel settings. */
if ( ! defined( 'ABSPATH' ) ) { exit; }

function smarttoolz_video_channel_settings_defaults() { return array( 'channels_enabled'=>1, 'allow_creator_customize'=>1, 'show_subscriber_count'=>1, 'show_video_count'=>1, 'default_banner_url'=>'' ); }
function smarttoolz_video_channel_settings() { return wp_parse_args( (array) get_option( 'smarttoolz_video_channel_settings', array() ), smarttoolz_video_channel_settings_defaults() ); }
function smarttoolz_video_channel_settings_sanitize( $input ) {
    $input=is_array($input)?$input:array();
    return array('channels_enabled'=>empty($input['channels_enabled'])?0:1,'allow_creator_customize'=>empty($input['allow_creator_customize'])?0:1,'show_subscriber_count'=>empty($input['show_subscriber_count'])?0:1,'show_video_count'=>empty($input['show_video_count'])?0:1,'default_banner_url'=>isset($input['default_banner_url'])?esc_url_raw($input['default_banner_url']):'');
}
add_action('admin_init','smarttoolz_video_channel_register_settings');
function smarttoolz_video_channel_register_settings(){register_setting('smarttoolz_video_channel_settings_group','smarttoolz_video_channel_settings',array('sanitize_callback'=>'smarttoolz_video_channel_settings_sanitize'));}
add_action('admin_menu','smarttoolz_video_channel_admin_menu',35);
function smarttoolz_video_channel_admin_menu(){add_submenu_page('smarttoolz','Channel Settings','Channel Settings','manage_options','smarttoolz-channel-settings','smarttoolz_video_channel_admin_page');}
function smarttoolz_video_channel_admin_page(){
    if(!current_user_can('manage_options'))return;$s=smarttoolz_video_channel_settings();
    echo '<div class="wrap"><h1>Channel Settings</h1><p>Configure the public creator channel. SmartToolz branding remains an administrator-side product brand.</p><form method="post" action="options.php">';settings_fields('smarttoolz_video_channel_settings_group');
    echo '<table class="form-table"><tr><th>Creator channels</th><td><label><input type="checkbox" name="smarttoolz_video_channel_settings[channels_enabled]" value="1" '.checked($s['channels_enabled'],1,false).'> Enable public channels</label></td></tr><tr><th>Creator customization</th><td><label><input type="checkbox" name="smarttoolz_video_channel_settings[allow_creator_customize]" value="1" '.checked($s['allow_creator_customize'],1,false).'> Allow users to customize their own channel</label></td></tr><tr><th>Subscriber count</th><td><label><input type="checkbox" name="smarttoolz_video_channel_settings[show_subscriber_count]" value="1" '.checked($s['show_subscriber_count'],1,false).'> Show subscriber count</label></td></tr><tr><th>Video count</th><td><label><input type="checkbox" name="smarttoolz_video_channel_settings[show_video_count]" value="1" '.checked($s['show_video_count'],1,false).'> Show published video count</label></td></tr><tr><th>Default banner URL</th><td><input class="regular-text" type="url" name="smarttoolz_video_channel_settings[default_banner_url]" value="'.esc_attr($s['default_banner_url']).'" placeholder="https://example.com/banner.jpg"></td></tr></table>';submit_button('Save Channel Settings');echo '</form></div>';
}

function smarttoolz_video_channel_resolve_user(){
    $handle=get_query_var('smarttoolz_video_channel','');
    if(''===$handle){$uri=isset($_SERVER['REQUEST_URI'])?wp_unslash($_SERVER['REQUEST_URI']):'';if(preg_match('#/@([A-Za-z0-9._-]+)(?:/|$)#',$uri,$m))$handle=$m[1];}
    if(''===$handle&&is_user_logged_in())return wp_get_current_user();if(''===$handle)return false;
    $handle=sanitize_user($handle,true);$u=get_user_by('slug',$handle);if(!$u)$u=get_user_by('login',$handle);return $u;
}
function smarttoolz_video_channel_banner_url($id){$u=get_user_meta($id,'smarttoolz_channel_banner_url',true);if($u)return esc_url($u);$s=smarttoolz_video_channel_settings();return !empty($s['default_banner_url'])?esc_url($s['default_banner_url']):'';}
function smarttoolz_video_channel_avatar_url($id){$u=get_user_meta($id,'smarttoolz_avatar_url',true);if($u)return esc_url($u);return esc_url(get_avatar_url($id,array('size'=>256)));}
function smarttoolz_video_channel_subscribers($id){$list=get_user_meta($id,'smarttoolz_subscribers',true);if(is_array($list))return count(array_unique(array_map('absint',$list)));return absint(get_user_meta($id,'smarttoolz_subscriber_count',true));}

function smarttoolz_video_channel_style(){
    $r=get_query_var('smarttoolz_video_route','');if(!in_array($r,array('channel','channel-videos','channel-shorts','channel-live','settings'),true))return;
    echo '<style id="stv-channel-style">.stv-channel{width:100%;max-width:1400px;margin:0 auto}.stv-channel__banner{height:220px;border-radius:12px;background:#252525 center/cover no-repeat}.stv-channel__identity{display:flex;gap:22px;align-items:flex-end;padding:0 28px;margin-top:-58px;position:relative}.stv-channel__avatar{width:132px;height:132px;border-radius:50%;border:5px solid #0f0f0f;background:#303030;display:flex;align-items:center;justify-content:center;color:#fff;font-size:48px;font-weight:800;object-fit:cover}.stv-channel__info{padding-bottom:12px;min-width:0}.stv-channel__eyebrow{font-size:12px;color:#aaa;text-transform:uppercase;letter-spacing:.08em}.stv-channel__name{font-size:34px;line-height:1.15;margin:5px 0 7px;color:#fff}.stv-channel__handle,.stv-channel__stats{color:#aaa;margin:0}.stv-channel__stats{margin-top:8px;font-size:14px}.stv-channel__actions{margin-left:auto;display:flex;gap:9px;align-items:center;padding-bottom:16px}.stv-channel__button{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:22px;padding:10px 18px;background:#fff;color:#111;text-decoration:none;font-weight:700}.stv-channel__button--secondary{background:#292929;color:#fff}.stv-channel__tabs{display:flex;gap:28px;border-bottom:1px solid #303030;margin-top:20px;padding:0 12px;overflow:auto}.stv-channel__tab{padding:15px 5px;color:#aaa;text-decoration:none;font-weight:600;white-space:nowrap;border-bottom:3px solid transparent}.stv-channel__tab--active,.stv-channel__tab:hover{color:#fff;border-bottom-color:#fff}.stv-channel__section{padding:24px 12px}.stv-channel__grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px 16px}.stv-channel-video__thumb{display:block;aspect-ratio:16/9;background:#202020;border-radius:10px;overflow:hidden;position:relative}.stv-channel-video__thumb img{width:100%;height:100%;object-fit:cover;display:block}.stv-channel-video__play{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:46px;height:46px;border-radius:50%;background:rgba(0,0,0,.8);color:#fff;display:flex;align-items:center;justify-content:center}.stv-channel-video__title{display:block;color:#fff;text-decoration:none;font-weight:700;margin-top:10px;line-height:1.35}.stv-channel-video__meta{color:#aaa;font-size:12px;margin-top:5px}.stv-channel__empty{padding:45px 20px;border:1px dashed #3a3a3a;border-radius:12px;color:#aaa;text-align:center}.stv-channel-settings{width:100%;max-width:900px;margin:0 auto}.stv-channel-settings__panel{background:#181818;border:1px solid #303030;border-radius:14px;padding:24px}.stv-channel-settings__form{display:grid;gap:16px}.stv-channel-settings__form label{display:grid;gap:7px;color:#ddd;font-weight:600;font-size:13px}.stv-channel-settings__form input,.stv-channel-settings__form textarea{width:100%;box-sizing:border-box;background:#101010;border:1px solid #3a3a3a;border-radius:9px;color:#fff;padding:11px 12px}.stv-channel-settings__form textarea{min-height:130px}.stv-channel-settings__notice{padding:11px 14px;margin:15px 0;border-radius:9px;background:#17331f;color:#a9efbd}@media(max-width:1000px){.stv-channel__grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:760px){.stv-channel__banner{height:150px}.stv-channel__identity{padding:0 12px;gap:13px;margin-top:-35px;flex-wrap:wrap}.stv-channel__avatar{width:88px;height:88px;font-size:32px}.stv-channel__name{font-size:25px}.stv-channel__actions{margin-left:101px;padding-bottom:0}.stv-channel__grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:480px){.stv-channel__grid{grid-template-columns:1fr}.stv-channel__actions{margin-left:0}}</style>';
}
add_action('wp_head','smarttoolz_video_channel_style',31);

function smarttoolz_video_channel_render($route){
    $s=smarttoolz_video_channel_settings();if(empty($s['channels_enabled'])){echo '<div class="stv-channel__empty">Channels are currently disabled.</div>';return;}
    $u=smarttoolz_video_channel_resolve_user();if(!$u){echo '<div class="stv-channel__empty">Channel not found.</div>';return;}
    $site=function_exists('smarttoolz_video_site_name')?smarttoolz_video_site_name():get_bloginfo('name');$handle=get_user_meta($u->ID,'smarttoolz_channel_handle',true);if(''===$handle)$handle=$u->user_nicename;$name=get_user_meta($u->ID,'smarttoolz_channel_name',true);if(''===$name)$name=$u->display_name?$u->display_name:$u->user_login;$desc=get_user_meta($u->ID,'smarttoolz_channel_description',true);$avatar=smarttoolz_video_channel_avatar_url($u->ID);$banner=smarttoolz_video_channel_banner_url($u->ID);$videos=get_posts(array('post_type'=>'stv_video','post_status'=>'publish','author'=>$u->ID,'posts_per_page'=>24,'orderby'=>'date','order'=>'DESC'));$count=count(get_posts(array('post_type'=>'stv_video','post_status'=>'publish','author'=>$u->ID,'posts_per_page'=>-1,'fields'=>'ids')));$subs=smarttoolz_video_channel_subscribers($u->ID);
    $tabs=array('channel'=>array('Home',smarttoolz_video_route_url('channel',$handle)),'channel-videos'=>array('Videos',smarttoolz_video_route_url('channel-videos',$handle)),'channel-shorts'=>array('Shorts',smarttoolz_video_route_url('channel-shorts',$handle)),'channel-live'=>array('Live',smarttoolz_video_route_url('channel-live',$handle)));$current=$route;
    ?>
    <section class="stv-channel"><div class="stv-channel__banner"<?php if($banner)echo ' style="background-image:url('.esc_url($banner).')"'; ?>></div><div class="stv-channel__identity"><?php if($avatar): ?><img class="stv-channel__avatar" src="<?php echo esc_url($avatar); ?>" alt="<?php echo esc_attr($name); ?>"><?php else: ?><div class="stv-channel__avatar"><?php echo esc_html(strtoupper(substr($name,0,1))); ?></div><?php endif; ?><div class="stv-channel__info"><span class="stv-channel__eyebrow"><?php echo esc_html($site); ?> Channel</span><h1 class="stv-channel__name"><?php echo esc_html($name); ?></h1><p class="stv-channel__handle">@<?php echo esc_html($handle); ?></p><p class="stv-channel__stats"><?php if(!empty($s['show_subscriber_count']))echo esc_html(number_format_i18n($subs)).' subscribers'; ?><?php if(!empty($s['show_subscriber_count'])&&!empty($s['show_video_count']))echo ' · '; ?><?php if(!empty($s['show_video_count']))echo esc_html(number_format_i18n($count)).' videos'; ?></p></div><div class="stv-channel__actions"><?php if(is_user_logged_in()&&get_current_user_id()===(int)$u->ID): ?><a class="stv-channel__button" href="<?php echo esc_url(smarttoolz_video_route_url('settings')); ?>">Customize channel</a><?php elseif(is_user_logged_in()): ?><a class="stv-channel__button" href="#subscribe">Subscribe</a><?php endif; ?></div></div><nav class="stv-channel__tabs" aria-label="Channel navigation"><?php foreach($tabs as $key=>$tab): ?><a class="stv-channel__tab <?php echo $current===$key?'stv-channel__tab--active':''; ?>" href="<?php echo esc_url($tab[1]); ?>"><?php echo esc_html($tab[0]); ?></a><?php endforeach; ?></nav><div class="stv-channel__section"><?php if($desc&&'channel'===$current): ?><p><?php echo esc_html($desc); ?></p><?php endif; ?><?php if('channel-live'===$current): ?><h2>Live</h2><div class="stv-channel__empty">No live videos right now.</div><?php elseif('channel-shorts'===$current): ?><h2>Shorts</h2><div class="stv-channel__empty">No Shorts have been published yet.</div><?php else: ?><h2><?php echo 'channel-videos'===$current?'Videos':'For you'; ?></h2><?php if(empty($videos)): ?><div class="stv-channel__empty">This channel has not published any videos yet.</div><?php else: ?><div class="stv-channel__grid"><?php foreach($videos as $video): ?><article class="stv-channel-video"><a class="stv-channel-video__thumb" href="<?php echo esc_url(smarttoolz_video_route_url('watch',$video->ID)); ?>"><?php if(has_post_thumbnail($video->ID))echo get_the_post_thumbnail($video->ID,'medium_large'); ?><span class="stv-channel-video__play">▶</span></a><a class="stv-channel-video__title" href="<?php echo esc_url(smarttoolz_video_route_url('watch',$video->ID)); ?>"><?php echo esc_html($video->post_title); ?></a><div class="stv-channel-video__meta"><?php echo esc_html($name); ?> · <?php echo esc_html(get_the_date('',$video)); ?></div></article><?php endforeach; ?></div><?php endif; ?><?php endif; ?></div></section>
    <?php
}
function smarttoolz_video_channel_template_redirect(){ $r=get_query_var('smarttoolz_video_route','');if(!in_array($r,array('channel','channel-videos','channel-shorts','channel-live'),true))return;get_header();smarttoolz_video_channel_render($r);get_footer();exit; }
add_action('template_redirect','smarttoolz_video_channel_template_redirect',99);

function smarttoolz_video_channel_settings_save(){
    if('settings'!==get_query_var('smarttoolz_video_route','')||!is_user_logged_in()||'POST'!==strtoupper($_SERVER['REQUEST_METHOD']))return;if(!isset($_POST['stv_channel_settings_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['stv_channel_settings_nonce'])),'stv_channel_settings_save'))return;if(empty(smarttoolz_video_channel_settings()['allow_creator_customize']))return;
    $id=get_current_user_id();$name=isset($_POST['stv_channel_name'])?sanitize_text_field(wp_unslash($_POST['stv_channel_name'])):'';$handle=isset($_POST['stv_channel_handle'])?sanitize_user(wp_unslash($_POST['stv_channel_handle']),true):'';$desc=isset($_POST['stv_channel_description'])?sanitize_textarea_field(wp_unslash($_POST['stv_channel_description'])):'';$avatar=isset($_POST['stv_channel_avatar'])?esc_url_raw(wp_unslash($_POST['stv_channel_avatar'])):'';$banner=isset($_POST['stv_channel_banner'])?esc_url_raw(wp_unslash($_POST['stv_channel_banner'])):'';$u=wp_get_current_user();if(''===$name)$name=$u->display_name?$u->display_name:$u->user_login;if(''===$handle)$handle=$u->user_nicename;
    update_user_meta($id,'smarttoolz_channel_name',$name);update_user_meta($id,'smarttoolz_channel_handle',$handle);update_user_meta($id,'smarttoolz_channel_description',$desc);update_user_meta($id,'smarttoolz_avatar_url',$avatar);update_user_meta($id,'smarttoolz_channel_banner_url',$banner);wp_safe_redirect(add_query_arg('stv_channel_saved','1',smarttoolz_video_route_url('settings')));exit;
}
add_action('template_redirect','smarttoolz_video_channel_settings_save',1);
function smarttoolz_video_channel_settings_template_redirect(){if('settings'!==get_query_var('smarttoolz_video_route',''))return;get_header();smarttoolz_video_channel_settings_render();get_footer();exit;}
function smarttoolz_video_channel_settings_render(){
    if(!is_user_logged_in()){wp_safe_redirect(smarttoolz_video_route_url('login'));exit;}$s=smarttoolz_video_channel_settings();if(empty($s['allow_creator_customize'])){echo '<div class="stv-channel__empty">Channel customization is disabled by the site administrator.</div>';return;}$u=wp_get_current_user();$name=get_user_meta($u->ID,'smarttoolz_channel_name',true);$handle=get_user_meta($u->ID,'smarttoolz_channel_handle',true);$desc=get_user_meta($u->ID,'smarttoolz_channel_description',true);$avatar=get_user_meta($u->ID,'smarttoolz_avatar_url',true);$banner=get_user_meta($u->ID,'smarttoolz_channel_banner_url',true);if(''===$name)$name=$u->display_name?$u->display_name:$u->user_login;if(''===$handle)$handle=$u->user_nicename;
    echo '<section class="stv-channel-settings"><div class="stv-channel-settings__panel"><span class="stv-channel__eyebrow">'.esc_html(get_bloginfo('name')).' Channel</span><h1 class="stv-page-title">Customize your channel</h1><p class="stv-section-subtitle">Update the public channel shown to visitors.</p>';if(isset($_GET['stv_channel_saved']))echo '<div class="stv-channel-settings__notice">Channel settings saved.</div>';echo '<form method="post" class="stv-channel-settings__form">';wp_nonce_field('stv_channel_settings_save','stv_channel_settings_nonce');echo '<label>Channel name<input type="text" name="stv_channel_name" maxlength="80" required value="'.esc_attr($name).'" /></label><label>Handle<input type="text" name="stv_channel_handle" maxlength="50" required value="'.esc_attr($handle).'" /></label><label>Description<textarea name="stv_channel_description" maxlength="1000">'.esc_textarea($desc).'</textarea></label><label>Avatar image URL<input type="url" name="stv_channel_avatar" value="'.esc_attr($avatar).'" /></label><label>Banner image URL<input type="url" name="stv_channel_banner" value="'.esc_attr($banner).'" /></label><div><button type="submit" class="stv-channel__button">Save channel</button> <a class="stv-channel__button stv-channel__button--secondary" href="'.esc_url(smarttoolz_video_route_url('channel',$handle)).'">View channel</a></div></form></div></section>';
    return true;
}
add_action('template_redirect','smarttoolz_video_channel_settings_template_redirect',99);
